import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(scriptDir, '..');
const outDir = path.join(rootDir, 'out');
const publicDir = path.join(rootDir, 'public');
const headersConfigPath = path.join(rootDir, 'lib/security/static-headers.json');
const defaultLocale = 'en';
const localeSegments = new Set(['en', 'zh']);

const sourceMapCommentPattern = /(?:^|\n)\s*(?:\/\/# sourceMappingURL=.*\.map\s*|\/\*# sourceMappingURL=.*\.map\s*\*\/\s*)$/gm;
const sourceMapReferencePattern = /sourceMappingURL=.*\.map/;

function readSecurityHeaders() {
  return JSON.parse(fs.readFileSync(headersConfigPath, 'utf8'));
}

function walkFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  return entries.flatMap((entry) => {
    const entryPath = path.join(dir, entry.name);
    return entry.isDirectory() ? walkFiles(entryPath) : entryPath;
  });
}

function removeSourceMaps(files) {
  let removed = 0;

  for (const file of files) {
    if (!file.endsWith('.map')) continue;
    fs.rmSync(file);
    removed += 1;
  }

  return removed;
}

function removeSourceMapComments(files) {
  let updated = 0;
  const extensions = new Set(['.js', '.mjs', '.cjs', '.css']);

  for (const file of files) {
    if (!extensions.has(path.extname(file))) continue;
    const source = fs.readFileSync(file, 'utf8');
    if (!sourceMapReferencePattern.test(source)) continue;

    const nextSource = source.replace(sourceMapCommentPattern, '');
    if (nextSource === source) continue;

    fs.writeFileSync(file, nextSource);
    updated += 1;
  }

  return updated;
}

function formatHeadersFile(headers) {
  const globalHeaders = headers
    .map(({ key, value }) => `  ${key}: ${value}`)
    .join('\n');

  return [
    '/*',
    globalHeaders,
    '',
    '/_next/static/*',
    '  Cache-Control: public, max-age=31536000, immutable',
    '',
    '/sw.js',
    '  Cache-Control: no-cache, no-store, must-revalidate',
    '  Service-Worker-Allowed: /',
    '',
    '/manifest.webmanifest',
    '  Cache-Control: public, max-age=86400',
    '',
    '/*.map',
    '  X-Robots-Tag: noindex, nofollow, noarchive',
    '  Cache-Control: no-store',
    '',
  ].join('\n');
}

function writeStaticHeaders() {
  fs.writeFileSync(path.join(outDir, '_headers'), formatHeadersFile(readSecurityHeaders()));
}

function getPublicRootHtmlFiles() {
  if (!fs.existsSync(publicDir)) return [];

  return fs
    .readdirSync(publicDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.html'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

function copyPublicRootHtmlFiles() {
  const htmlFiles = getPublicRootHtmlFiles();

  for (const filename of htmlFiles) {
    fs.copyFileSync(path.join(publicDir, filename), path.join(outDir, filename));
  }

  return htmlFiles.length;
}

function normalizePathSeparators(filePath) {
  return filePath.split(path.sep).join('/');
}

function getRoutePathFromHtmlFile(file) {
  const relativePath = normalizePathSeparators(path.relative(outDir, file));
  if (!relativePath.endsWith('.html')) return null;
  if (relativePath === 'index.html') return '/';

  return `/${relativePath.slice(0, -'.html'.length)}`;
}

function hasDefaultLocalePage(routePath) {
  const routeSegments = routePath.split('/').filter(Boolean);
  const localizedHtmlPath = path.join(outDir, defaultLocale, ...routeSegments) + '.html';

  return fs.existsSync(localizedHtmlPath);
}

function shouldCreateDefaultLocaleRedirect(routePath) {
  if (!routePath || routePath === '/') return false;

  const firstSegment = routePath.split('/').filter(Boolean)[0];
  if (!firstSegment) return false;
  if (localeSegments.has(firstSegment)) return false;
  if (firstSegment.startsWith('_')) return false;
  if (routePath === '/404') return false;

  return hasDefaultLocalePage(routePath);
}

function collectDefaultLocaleRedirects() {
  return walkFiles(outDir)
    .map(getRoutePathFromHtmlFile)
    .filter(shouldCreateDefaultLocaleRedirect)
    .sort((a, b) => a.localeCompare(b));
}

function formatRedirectsFile(routePaths, passthroughHtmlFiles) {
  const passthroughLines = passthroughHtmlFiles.map((filename) => {
    const routePath = `/${filename}`;
    return `${routePath} ${routePath} 200`;
  });
  const redirectLines = routePaths.flatMap((routePath) => [
    `${routePath} /${defaultLocale}${routePath} 302`,
    `${routePath}/ /${defaultLocale}${routePath} 302`,
  ]);

  return [
    '# Generated by scripts/harden-static-export.mjs',
    '# Root public HTML files are search-engine verification assets and must keep their .html URL.',
    ...passthroughLines,
    passthroughLines.length > 0 ? '' : null,
    '# Non-localized compatibility routes are redirected at the edge to reduce static export file count.',
    ...redirectLines,
    '',
  ].filter((line) => line !== null).join('\n');
}

function countFiles(targetPath) {
  if (!fs.existsSync(targetPath)) return 0;
  const stats = fs.statSync(targetPath);

  return stats.isDirectory() ? walkFiles(targetPath).length : 1;
}

function pruneDefaultLocaleRedirectExports() {
  const routePaths = collectDefaultLocaleRedirects();
  const passthroughHtmlFiles = getPublicRootHtmlFiles();
  if (routePaths.length === 0 && passthroughHtmlFiles.length === 0) {
    return { redirects: 0, removedFiles: 0 };
  }

  fs.writeFileSync(path.join(outDir, '_redirects'), formatRedirectsFile(routePaths, passthroughHtmlFiles));

  const topLevelSegments = new Set(
    routePaths.map((routePath) => routePath.split('/').filter(Boolean)[0])
  );
  let removedFiles = 0;

  for (const segment of topLevelSegments) {
    const routeHtmlFile = path.join(outDir, `${segment}.html`);
    const routeTxtFile = path.join(outDir, `${segment}.txt`);
    const routeDirectory = path.join(outDir, segment);

    for (const targetPath of [routeHtmlFile, routeTxtFile, routeDirectory]) {
      removedFiles += countFiles(targetPath);
      fs.rmSync(targetPath, { recursive: true, force: true });
    }
  }

  return { redirects: routePaths.length, removedFiles };
}

if (!fs.existsSync(outDir)) {
  throw new Error(`Static export directory not found: ${outDir}`);
}

const filesBeforeCleanup = walkFiles(outDir);
const removedMaps = removeSourceMaps(filesBeforeCleanup);
const updatedReferences = removeSourceMapComments(walkFiles(outDir));
writeStaticHeaders();
const prunedRedirectExports = pruneDefaultLocaleRedirectExports();
const copiedPublicHtmlFiles = copyPublicRootHtmlFiles();

const remainingMaps = walkFiles(outDir).filter((file) => file.endsWith('.map'));
if (remainingMaps.length > 0) {
  throw new Error(`Source maps remain in static export:\n${remainingMaps.join('\n')}`);
}

console.log(
  `Hardened static export: removed ${removedMaps} source map file(s), stripped ${updatedReferences} source map reference(s), wrote out/_headers, wrote ${prunedRedirectExports.redirects} redirect(s), pruned ${prunedRedirectExports.removedFiles} redirect export file(s), copied ${copiedPublicHtmlFiles} root public HTML file(s).`
);
